param($f)
$alts = @('gh[pousr]_[A-Za-z0-9]{20,}','github_pat_[A-Za-z0-9_]{40,}','AIza[0-9A-Za-z_-]{30,}','(?<![A-Za-z0-9_-])sk-[A-Za-z0-9_-]{20,}','xox[baprs]-[A-Za-z0-9-]{10,}','apikey_[A-Za-z0-9]{20,}','(KEY|TOKEN|SECRET|PASSWORD)[A-Z_]*=["'']?[A-Za-z0-9_\-]{16,}')
